def tpat(s):
    s = str(s)
    if not s: return "blank"
    if re.fullmatch(r"\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ", s): return "ISO-8601 with Z"
    if re.fullmatch(r"\d{4}-\d\d-\d\dT\d{1,2}:\d\d:\d\d", s): return "ISO-like without timezone"
    return "other: " + re.sub(r"\d", "9", s)[:24]
